package org.brightstats.desktop;
import java.util.*;
import com.google.gson.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.data.NonlinearInput;
import org.brightstats.stats.*;

final class NonlinearDialog {
    enum Template {MODERATION,THREE_WAY,QUADRATIC,CUBIC,QUADRATIC_MODERATION;
        @Override public String toString(){return switch(this){case MODERATION->"Two-way interaction (X × W)";case THREE_WAY->"Three-way interaction (X × W × Z)";case QUADRATIC->"Quadratic effect (X²)";case CUBIC->"Cubic effect (X³)";case QUADRATIC_MODERATION->"Moderated quadratic effect (X² × W)";};}}
    record Settings(NonlinearPls.Specification specification,Bootstrap.Options bootstrap){Settings{Objects.requireNonNull(specification);Objects.requireNonNull(bootstrap);}}
    private final Dialog<Settings> dialog=new Dialog<>();private final ComboBox<Template> template=new ComboBox<>();
    private final ComboBox<String> x=new ComboBox<>(),y=new ComboBox<>(),w=new ComboBox<>(),z=new ComboBox<>();
    private final TextField probeValues=new TextField("-1,0,1"),secondValues=new TextField("0"),lower=new TextField("-2"),upper=new TextField("2"),points=new TextField("41"),samples=new TextField(),seed=new TextField(),confidence=new TextField();
    private final ComboBox<BootstrapIntervals.Method> interval=new ComboBox<>();private final TextArea advanced=new TextArea();private final TabPane modes=new TabPane();private final Label error=new Label();
    private final List<PlsSem.Block> blocks;private final List<PlsSem.Edge> edges;private final PlsSem.Options options;private Settings result;
    NonlinearDialog(Window owner,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Settings previous,boolean resampling){
        if(blocks.size()<2)throw new IllegalArgumentException("Create at least two measured constructs first.");this.blocks=List.copyOf(blocks);this.edges=List.copyOf(edges);this.options=options;
        dialog.initOwner(owner);dialog.setTitle(resampling?"Two-stage nonlinear PLS bootstrap":"Latent moderation and polynomial effects");dialog.setResizable(true);var names=blocks.stream().map(PlsSem.Block::name).toList();for(var combo:List.of(x,y,w,z))combo.getItems().setAll(names);
        int source=edges.isEmpty()?0:edges.getFirst().source(),target=edges.isEmpty()?names.size()-1:edges.getFirst().target();x.getSelectionModel().select(source);y.getSelectionModel().select(target);int moderator=0;for(int j=0;j<names.size();j++)if(j!=source&&j!=target){moderator=j;break;}w.getSelectionModel().select(moderator);int second=moderator;for(int j=0;j<names.size();j++)if(j!=source&&j!=target&&j!=moderator){second=j;break;}z.getSelectionModel().select(second);
        template.getItems().setAll(Template.values());template.setValue(names.size()==2?Template.QUADRATIC:Template.MODERATION);var boot=previous==null?new Bootstrap.Options(5000,42,.95):previous.bootstrap();samples.setText(Integer.toString(boot.samples()));seed.setText(Long.toString(boot.seed()));confidence.setText(Double.toString(boot.confidence()));interval.getItems().setAll(BootstrapIntervals.Method.PERCENTILE,BootstrapIntervals.Method.BCA);interval.setValue(boot.interval()==BootstrapIntervals.Method.BCA?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE);
        GridPane builder=new GridPane();builder.setHgap(14);builder.setVgap(9);builder.addRow(0,UiAppearance.label("Relationship"),template);builder.addRow(1,UiAppearance.label("Predictor X"),x);builder.addRow(2,UiAppearance.label("Outcome"),y);builder.addRow(3,UiAppearance.label("Moderator W (interactions)"),w);builder.addRow(4,UiAppearance.label("Moderator Z (three-way)"),z);builder.addRow(5,UiAppearance.label("W probes / X probes for powers"),probeValues);builder.addRow(6,UiAppearance.label("Z probes (three-way)"),secondValues);builder.addRow(7,UiAppearance.label("Focal-score curve minimum"),lower);builder.addRow(8,UiAppearance.label("Focal-score curve maximum"),upper);builder.addRow(9,UiAppearance.label("Fixed curve points"),points);builder.setPadding(new Insets(12));
        advanced.setPrefRowCount(16);advanced.setText(new GsonBuilder().setPrettyPrinting().create().toJson(previous==null?buildSpecification():previous.specification()));Button copyBuilder=UiAppearance.button("Replace with builder settings");copyBuilder.setOnAction(event->{try{advanced.setText(new GsonBuilder().setPrettyPrinting().create().toJson(buildSpecification()));error.setText("");}catch(RuntimeException problem){error.setText(problem.getMessage());}});Label schema=UiAppearance.label("Full specification supports multiple relationships. Use zero-based construct indices, extensions [{target,factors}], named probes with values {index:value}, and an optional fixed grid. Repeated factors create powers; lower-order terms are automatic.");schema.setWrapText(true);VBox custom=new VBox(8,schema,copyBuilder,advanced);custom.setPadding(new Insets(12));Tab basicTab=new Tab("Build relationship",builder),advancedTab=new Tab("Full specification",custom);basicTab.setClosable(false);advancedTab.setClosable(false);modes.getTabs().addAll(basicTab,advancedTab);if(previous!=null)modes.getSelectionModel().select(advancedTab);
        GridPane resample=new GridPane();resample.setHgap(14);resample.setVgap(8);resample.addRow(0,UiAppearance.label("Bootstrap attempts"),samples);resample.addRow(1,UiAppearance.label("Seed"),seed);resample.addRow(2,UiAppearance.label("Confidence (0–1)"),confidence);resample.addRow(3,UiAppearance.label("Standard case interval"),interval);for(var node:List.of(samples,seed,confidence,interval))node.setDisable(!resampling);
        Label guidance=UiAppearance.label("First fit the main-effects PLS model, then regress the unit-variance composite scores on hierarchical raw products. Lower-order effects are added automatically. This is composite-score PLS, not PLSc. Full bootstrap refits both stages; local derivatives and pointwise curves do not establish causality.");guidance.setWrapText(true);error.setWrapText(true);error.setStyle("-fx-text-fill:#a02020");VBox content=new VBox(10,guidance,modes,resample,error);content.setPadding(new Insets(12));content.setPrefWidth(780);ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(700);dialog.getDialogPane().setContent(scroll);ButtonType run=new ButtonType(resampling?"Bootstrap":"Calculate",ButtonBar.ButtonData.OK_DONE);dialog.getDialogPane().getButtonTypes().addAll(run,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(run).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{result=resolve();error.setText("");}catch(RuntimeException problem){error.setText(problem.getMessage());event.consume();}});dialog.setResultConverter(button->button==run?result:null);
    }
    private static double[] values(String text){String[] parts=text.trim().split(",");double[] result=new double[parts.length];for(int j=0;j<parts.length;j++){result[j]=Double.parseDouble(parts[j].trim());if(!Double.isFinite(result[j]))throw new IllegalArgumentException("Probe values must be finite.");}return result;}
    private static void distinct(int... indices){if(Arrays.stream(indices).distinct().count()!=indices.length)throw new IllegalArgumentException("Choose distinct predictor, moderator and outcome roles for this template.");}
    private NonlinearPls.Specification buildSpecification(){int source=x.getSelectionModel().getSelectedIndex(),target=y.getSelectionModel().getSelectedIndex(),moderator=w.getSelectionModel().getSelectedIndex(),second=z.getSelectionModel().getSelectedIndex();int[] factors;var kind=template.getValue();switch(kind){case MODERATION->{distinct(source,moderator,target);factors=new int[]{source,moderator};}case THREE_WAY->{distinct(source,moderator,second,target);factors=new int[]{source,moderator,second};}case QUADRATIC->{distinct(source,target);factors=new int[]{source,source};}case CUBIC->{distinct(source,target);factors=new int[]{source,source,source};}case QUADRATIC_MODERATION->{distinct(source,moderator,target);factors=new int[]{source,source,moderator};}default->throw new IllegalArgumentException("Select a polynomial template.");}
        List<PathProcess.Probe> probes=new ArrayList<>();boolean power=kind==Template.QUADRATIC||kind==Template.CUBIC;int condition=power?source:moderator;for(double value:values(probeValues.getText()))for(double other:kind==Template.THREE_WAY?values(secondValues.getText()):new double[]{0}){Map<Integer,Double> coordinates=new LinkedHashMap<>();coordinates.put(condition,value);String name=blocks.get(condition).name()+"="+value;if(kind==Template.THREE_WAY){coordinates.put(second,other);name+="; "+blocks.get(second).name()+"="+other;}probes.add(new PathProcess.Probe(name,coordinates));}
        return new NonlinearPls.Specification(List.of(new NonlinearPls.Extension(target,factors)),probes,new NonlinearPls.Grid(source,target,Double.parseDouble(lower.getText().trim()),Double.parseDouble(upper.getText().trim()),Integer.parseInt(points.getText().trim())));}
    private Settings resolve(){var specification=modes.getSelectionModel().getSelectedIndex()==1?NonlinearInput.specification(JsonParser.parseString(advanced.getText())):buildSpecification();NonlinearPls.validate(blocks,edges,options,specification);return new Settings(specification,new Bootstrap.Options(Integer.parseInt(samples.getText().trim()),Long.parseLong(seed.getText().trim()),Double.parseDouble(confidence.getText().trim()),interval.getValue(),RegressionBootstrap.Convention.STANDARD,true));}
    static Optional<Settings> show(Window owner,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Settings previous,boolean resampling){return new NonlinearDialog(owner,blocks,edges,options,previous,resampling).dialog.showAndWait();}
    static Settings smokeTest(Window owner,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options){var probe=new NonlinearDialog(owner,blocks,edges,options,null,true);Button run=(Button)probe.dialog.getDialogPane().lookupButton(probe.dialog.getDialogPane().getButtonTypes().getFirst());javafx.application.Platform.runLater(()->{try{probe.samples.setText("29");run.fire();if(!probe.dialog.isShowing()||probe.error.getText().isBlank())throw new AssertionError("Invalid nonlinear attempts accepted");probe.samples.setText("40");probe.confidence.setText("1");run.fire();if(!probe.dialog.isShowing()||probe.error.getText().isBlank())throw new AssertionError("Invalid nonlinear confidence accepted");probe.confidence.setText(".95");probe.modes.getSelectionModel().select(1);probe.advanced.setText("{\"extensions\":[{\"target\":2,\"factors\":[0,0.5]}]}");run.fire();if(!probe.dialog.isShowing()||probe.error.getText().isBlank())throw new AssertionError("Fractional nonlinear indices accepted");probe.modes.getSelectionModel().select(0);run.fire();}catch(Throwable problem){probe.dialog.close();throw problem;}});return probe.dialog.showAndWait().orElseThrow(()->new AssertionError("Nonlinear dialog did not accept valid settings"));}
}
